1: <#
2: .SYNOPSIS
3:     Automated Project Identification and Safe Renaming Engine
4: #>
5: 
6: param(
7:     [string]$TargetDir = "C:\recover",
8:     [ValidateSet("Audit", "Apply")]
9:     [string]$Mode = "Audit"
10: )
11: 
12: $ErrorActionPreference = "Continue"
13: 
14: Write-Host "`n=======================================================" -ForegroundColor Cyan
15: Write-Host "   AUTOMATED PROJECT IDENTIFICATION & AUDIT ENGINE     " -ForegroundColor Cyan
16: Write-Host "   Target Directory: $TargetDir" -ForegroundColor Gray
17: Write-Host "   Execution Mode:   $Mode" -ForegroundColor $(if ($Mode -eq "Audit") { "Yellow" } else { "Green" })
18: Write-Host "=======================================================`n" -ForegroundColor Cyan
19: 
20: if (-not (Test-Path $TargetDir)) {
21:     Write-Error "Target directory '$TargetDir' does not exist."
22:     exit 1
23: }
24: 
25: $CandidateFolders = Get-ChildItem -Path $TargetDir -Directory | Where-Object { $_.Name -ne "dumpback.dat" }
26: 
27: if ($CandidateFolders.Count -eq 0) {
28:     Write-Host "[INFO] No subdirectories found in $TargetDir yet." -ForegroundColor Yellow
29:     exit 0
30: }
31: 
32: Write-Host "Found $($CandidateFolders.Count) candidate folder(s) to analyze.`n" -ForegroundColor White
33: 
34: $Results = @()
35: $RenamesToApply = @()
36: 
37: foreach ($folder in $CandidateFolders) {
38:     $folderPath = $folder.FullName
39:     $origName = $folder.Name
40:     $identifiedName = $null
41:     $ruleUsed = $null
42:     $confidence = "None"
43: 
44:     # Rule 1: Eclipse .project file XML
45:     $dotProject = Join-Path $folderPath ".project"
46:     if (Test-Path $dotProject) {
47:         try {
48:             [xml]$xml = Get-Content $dotProject -ErrorAction Stop
49:             if ($xml.projectDescription.name) {
50:                 $identifiedName = $xml.projectDescription.name.Trim()
51:                 $ruleUsed = "Eclipse .project XML"
52:                 $confidence = "100%"
53:             }
54:         } catch {
55:             $raw = Get-Content $dotProject -Raw -ErrorAction SilentlyContinue
56:             if ($raw -match '<name>\s*([^<]+)\s*</name>') {
57:                 $identifiedName = $matches[1].Trim()
58:                 $ruleUsed = "Eclipse .project Regex"
59:                 $confidence = "95%"
60:             }
61:         }
62:     }
63: 
64:     # Rule 2: Eclipse / CDT .cproject strings (contains original workspace paths)
65:     if (-not $identifiedName) {
66:         $dotCProject = Join-Path $folderPath ".cproject"
67:         if (Test-Path $dotCProject) {
68:             $raw = Get-Content $dotCProject -Raw -ErrorAction SilentlyContinue
69:             # Match original paths like D:\Claude\RVMON\... or D:\MNS\B17\...
70:             if ($raw -match '([A-Za-z]:\\[A-Za-z0-9_.\-\\]+)') {
71:                 $matchedPath = $matches[1]
72:                 # Extract the top 2 path segments under D:\ (e.g. Claude\RVMON or MNS\B17-135)
73:                 if ($matchedPath -match '^[A-Za-z]:\\([^\\]+\\[^\\]+)') {
74:                     $identifiedName = $matches[1] -replace '\\', '_'
75:                     $ruleUsed = ".cproject build path ($matchedPath)"
76:                     $confidence = "95%"
77:                 } else {
78:                     $identifiedName = [System.IO.Path]::GetFileName($matchedPath)
79:                     $ruleUsed = ".cproject path token"
80:                     $confidence = "80%"
81:                 }
82:             } elseif ($raw -match 'pdomName\s+/([A-Za-z0-9_.\-]+)') {
83:                 $identifiedName = $matches[1]
84:                 $ruleUsed = ".cproject pdomName"
85:                 $confidence = "85%"
86:             }
87:         }
88:     }
89: 
90:     # Rule 3: STM32CubeMX .ioc file
91:     if (-not $identifiedName) {
92:         $iocFiles = Get-ChildItem -Path $folderPath -Filter "*.ioc" -File -ErrorAction SilentlyContinue
93:         if ($iocFiles -and $iocFiles.Count -gt 0) {
94:             $identifiedName = $iocFiles[0].BaseName
95:             $ruleUsed = "STM32CubeMX .ioc ($($iocFiles[0].Name))"
96:             $confidence = "100%"
97:         }
98:     }
99: 
100:     # Rule 4: Git Repository (.git/config or root config)
101:     if (-not $identifiedName) {
102:         $gitConfigs = @(
103:             (Join-Path $folderPath ".git\config"),
104:             (Join-Path $folderPath "config")
105:         )
106:         foreach ($cfg in $gitConfigs) {
107:             if (Test-Path $cfg) {
108:                 $cfgContent = Get-Content $cfg -Raw -ErrorAction SilentlyContinue
109:                 if ($cfgContent -match 'url\s*=\s*.*?/([^/\r\n]+?)(?:\.git)?\s*$') {
110:                     $identifiedName = $matches[1].Trim()
111:                     $ruleUsed = "Git Remote URL ($($matches[1]))"
112:                     $confidence = "100%"
113:                     break
114:                 }
115:             }
116:         }
117:     }
118: 
119:     # Rule 5: PlatformIO (platformio.ini)
120:     if (-not $identifiedName) {
121:         $pio = Join-Path $folderPath "platformio.ini"
122:         if (Test-Path $pio) {
123:             $pioContent = Get-Content $pio -Raw -ErrorAction SilentlyContinue
124:             if ($pioContent -match 'description\s*=\s*([^\r\n]+)') {
125:                 $identifiedName = $matches[1].Trim() -replace '[^\w\-_]', '_'
126:                 $ruleUsed = "PlatformIO description"
127:                 $confidence = "90%"
128:             } elseif ($pioContent -match 'default_envs\s*=\s*([^\r\n]+)') {
129:                 $identifiedName = "PIO_" + $matches[1].Trim()
130:                 $ruleUsed = "PlatformIO default_envs"
131:                 $confidence = "85%"
132:             }
133:         }
134:     }
135: 
136:     # Rule 6: CMake (CMakeLists.txt)
137:     if (-not $identifiedName) {
138:         $cmake = Join-Path $folderPath "CMakeLists.txt"
139:         if (Test-Path $cmake) {
140:             $cmakeContent = Get-Content $cmake -Raw -ErrorAction SilentlyContinue
141:             if ($cmakeContent -match 'project\s*\(\s*["'']?([A-Za-z0-9_\-\.]+)["'']?') {
142:                 $identifiedName = $matches[1].Trim()
143:                 $ruleUsed = "CMakeLists project()"
144:                 $confidence = "95%"
145:             }
146:         }
147:     }
148: 
149:     # Rule 7: Visual Studio (.sln / .vcxproj)
150:     if (-not $identifiedName) {
151:         $sln = Get-ChildItem -Path $folderPath -Filter "*.sln" -File -ErrorAction SilentlyContinue
152:         if ($sln -and $sln.Count -gt 0) {
153:             $identifiedName = $sln[0].BaseName
154:             $ruleUsed = "Visual Studio Solution"
155:             $confidence = "95%"
156:         }
157:     }
158: 
159:     # Rule 8: Node.js (package.json)
160:     if (-not $identifiedName) {
161:         $pkg = Join-Path $folderPath "package.json"
162:         if (Test-Path $pkg) {
163:             try {
164:                 $json = Get-Content $pkg -Raw | ConvertFrom-Json
165:                 if ($json.name) {
166:                     $identifiedName = $json.name.Trim() -replace '[@/]', '_'
167:                     $ruleUsed = "package.json name"
168:                     $confidence = "95%"
169:                 }
170:             } catch {}
171:         }
172:     }
173: 
174:     # Sanitize identified name for Windows filesystem
175:     if ($identifiedName) {
176:         $cleanName = [string]::Join("_", $identifiedName.Split([System.IO.Path]::GetInvalidFileNameChars()))
177:     } else {
178:         $cleanName = "UNKNOWN_$origName"
179:         $ruleUsed = "No manifest found"
180:         $confidence = "0%"
181:     }
182: 
183:     $allFiles = Get-ChildItem -Path $folderPath -Recurse -File -ErrorAction SilentlyContinue
184:     $fileCount = if ($allFiles) { $allFiles.Count } else { 0 }
185:     $totalBytes = 0
186:     if ($allFiles) {
187:         $allFiles | ForEach-Object { $totalBytes += $_.Length }
188:     }
189:     $sizeMB = [math]::Round($totalBytes / 1MB, 2)
190: 
191:     $resultObj = [PSCustomObject]@{
192:         OriginalFolder  = $origName
193:         IdentifiedName  = $cleanName
194:         RuleUsed        = $ruleUsed
195:         Confidence      = $confidence
196:         FileCount       = $fileCount
197:         SizeMB          = $sizeMB
198:         Status          = if ($confidence -ne "0%") { "MATCHED" } else { "MANUAL_REVIEW" }
199:     }
200:     $Results += $resultObj
201: 
202:     if ($confidence -ne "0%") {
203:         $RenamesToApply += [PSCustomObject]@{
204:             SourcePath = $folderPath
205:             TargetName = $cleanName
206:             ParentDir  = $folder.Parent.FullName
207:         }
208:     }
209: }
210: 
211: $Results | Format-Table OriginalFolder, IdentifiedName, RuleUsed, Confidence, FileCount, SizeMB, Status -AutoSize
212: 
213: $csvPath = Join-Path $TargetDir "project_audit_report.csv"
214: $Results | Export-Csv -Path $csvPath -NoTypeInformation -Encoding UTF8
215: Write-Host "`n[AUDIT LOG] Written to: $csvPath" -ForegroundColor Green
216: 
217: if ($Mode -eq "Apply") {
218:     Write-Host "`n[APPLY MODE] Executing safe renames..." -ForegroundColor Yellow
219:     $rollbackList = @()
220: 
221:     foreach ($item in $RenamesToApply) {
222:         $destPath = Join-Path $item.ParentDir $item.TargetName
223:         $collisionIndex = 1
224:         $finalTargetName = $item.TargetName
225: 
226:         while (Test-Path $destPath) {
227:             $finalTargetName = "$($item.TargetName)_$collisionIndex"
228:             $destPath = Join-Path $item.ParentDir $finalTargetName
229:             $collisionIndex++
230:         }
231: 
232:         try {
233:             Rename-Item -Path $item.SourcePath -NewName $finalTargetName -ErrorAction Stop
234:             Write-Host "  [RENAMED] $($item.SourcePath) -> $finalTargetName" -ForegroundColor Green
235:             $rollbackList += [PSCustomObject]@{
236:                 OriginalName = [System.IO.Path]::GetFileName($item.SourcePath)
237:                 RenamedTo    = $finalTargetName
238:                 FullPath     = $destPath
239:             }
240:         } catch {
241:             Write-Host "  [ERROR] Failed to rename $($item.SourcePath): $_" -ForegroundColor Red
242:         }
243:     }
244: 
245:     $rollbackPath = Join-Path $TargetDir "rename_rollback.json"
246:     $rollbackList | ConvertTo-Json -Depth 3 | Set-Content -Path $rollbackPath -Encoding UTF8
247:     Write-Host "`n[ROLLBACK SAVED] Rollback manifest saved to: $rollbackPath" -ForegroundColor Green
248: } else {
249:     Write-Host "`n[AUDIT COMPLETE] Run with -Mode Apply to perform the safe rename." -ForegroundColor Cyan
250: }

