39:             
40:             # Check for critical project signatures
41:             $isMarker = $false
42:             $markerType = $null
43:             
44:             if ($fileName -eq ".project") { $isMarker = $true; $markerType = "dot_project" }
45:             elseif ($fileName -eq ".cproject") { $isMarker = $true; $markerType = "dot_cproject" }
46:             elseif ($fileName -like "*.ioc") { $isMarker = $true; $markerType = "ioc:$fileName" }
47:             elseif ($fileName -eq "platformio.ini") { $isMarker = $true; $markerType = "platformio" }
48:             elseif ($fileName -eq "cmakelists.txt") { $isMarker = $true; $markerType = "cmake" }
