import urllib.request, lzma, gzip, hashlib, os, re

def parse_deb_stanzas(text):
    pkgs = []
    cur = {}
    last_k = None
    for line in text.splitlines():
        if not line.strip():
            if cur:
                pkgs.append(cur)
                cur = {}
                last_k = None
            continue
        if line[0] in (' ', '\t') and last_k:
            cur[last_k] += '\n' + line
        elif ':' in line:
            k, v = line.split(':', 1)
            last_k = k.strip()
            cur[last_k] = v.strip()
    if cur:
        pkgs.append(cur)
    return pkgs

# 1. Load installed packages from Trixie dpkg status
status_txt = open(r'D:\JRFK\tools\trixie_dpkg_status.txt', encoding='utf-8').read()
installed = set()
for st in parse_deb_stanzas(status_txt):
    if 'install ok installed' in st.get('Status', ''):
        installed.add(st['Package'])
        for p in st.get('Provides', '').split(','):
            pn = p.strip().split()[0] if p.strip() else ''
            if pn:
                installed.add(pn)
print('Installed packages/provides:', len(installed))

# 2. Fetch arm64 Packages indexes
feeds = [
    ('http://archive.raspberrypi.com/debian/', 'http://archive.raspberrypi.com/debian/dists/trixie/main/binary-arm64/Packages.gz', 'gz'),
    ('http://deb.debian.org/debian/', 'http://deb.debian.org/debian/dists/trixie/main/binary-arm64/Packages.xz', 'xz'),
    ('http://deb.debian.org/debian/', 'http://deb.debian.org/debian/dists/trixie-updates/main/binary-arm64/Packages.xz', 'xz'),
]
repo = {}
provides_map = {}
for base_url, idx_url, comp in feeds:
    print('Fetching', idx_url)
    raw = urllib.request.urlopen(idx_url, timeout=30).read()
    txt = (gzip.decompress(raw) if comp == 'gz' else lzma.decompress(raw)).decode('utf-8', errors='replace')
    for st in parse_deb_stanzas(txt):
        pkg = st.get('Package')
        if not pkg:
            continue
        st['_base_url'] = base_url
        if pkg not in repo:
            repo[pkg] = st
        for p in st.get('Provides', '').split(','):
            pn = p.strip().split()[0] if p.strip() else ''
            if pn:
                provides_map.setdefault(pn, pkg)

# 3. Resolve missing dependency closure
wanted = ['python3-pil.imagetk', 'python3-can', 'can-utils', 'python3-paramiko', 'python3-hamlib', 'python3-websocket']
to_download = {}
queue = list(wanted)
seen = set()

def parse_deps(dep_str):
    out = []
    if not dep_str:
        return out
    for group in dep_str.split(','):
        alts = [a.strip().split()[0].split(':')[0] for a in group.split('|') if a.strip()]
        if alts:
            out.append(alts)
    return out

while queue:
    name = queue.pop(0)
    if name in installed or name in seen:
        continue
    seen.add(name)
    pkg = name if name in repo else provides_map.get(name)
    if not pkg or pkg not in repo:
        print('WARNING: package not found in repo:', name)
        continue
    if pkg in installed:
        continue
    st = repo[pkg]
    to_download[pkg] = st
    for field in ('Pre-Depends', 'Depends'):
        for alts in parse_deps(st.get(field, '')):
            if any(a in installed or a in to_download for a in alts):
                continue
            # Prefer first alt that exists in repo
            chosen = next((a for a in alts if a in repo or a in provides_map), alts[0])
